parameters.style:
html, body { background-color: var(--background); }

/* R15 — a sideways strip inside the page grid must not widen the page. */
.planner-scroll-x { min-width: 0; overflow-x: auto; }
.planner-pinned { min-width: 0; }

/* The phone shows one day (2026-09-21). Six columns do not fit at 390px, and the page
   does not scroll sideways by ruling — so the picked column is the only one drawn and
   the day picker chooses it. Above the breakpoint the picker is the thing that is gone. */
.planner-daypicker { display: none !important; }
@media (max-width: 700px) {
  .planner-daypicker { display: flex !important; }
  .planner-day { display: none !important; }
  .planner-day-picked { display: flex !important; width: 100% !important; }
  .planner-envs { flex-wrap: wrap; }
  .planner-envs > * { flex: 1 1 45% !important; min-width: 0 !important; }
  /* Two tiles to a line leaves about 170px, and "ADMIN AND ASKS" beside "5.25 h left"
     does not fit in it — the hours were cut off mid-number. The head wraps instead. */
  .planner-env-head { flex-wrap: wrap !important; }
  /* What opens over the week is sized for a laptop: 50% of 390px is a 195px sheet, and
     the projects card is two columns of 148px and 242px. On a phone they take the room. */
  .planner-over { width: 96% !important; max-width: none !important; max-height: 92% !important; }
  .planner-over-col { width: 100% !important; }
  .planner-over { flex-direction: column !important; }
  /* The app bar is one row of five controls; at 390px the last three fall off the end
     of it, and one of them is Shut down — the evening the whole app is built around. */
  .planner-appbar { flex-wrap: wrap !important; row-gap: var(--space-2) !important; }
  /* One day column is taller than a phone, so the phone has to scroll — and bodyScroll
     is a PROJECT setting, not a per-viewport one, so it cannot be turned on for narrow
     screens alone. These four lines are the deploy shell’s OWN `.body-scroll > #root`
     rule, applied under the breakpoint: with `bodyScroll: false` the shell pins #root
     `position: fixed; overflow: clip; height: 100%`, which CLIPS rather than scrolls —
     53 of 205 texts were on the page and no scroll reached them. R5 keeps its meaning
     where it was ruled: on a laptop the week fits and nothing scrolls. */
  body > #root { position: static !important; overflow: visible !important; height: auto !important; min-height: 100vh !important; flex-direction: column !important; }
  .planner-page { overflow-x: hidden; }
}

/* Dark: the system asks for it and the person has not chosen light. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --background: #161718;
    --foreground: #e7e7e4;
    --surface: #1f2022;
    --surface-raised: #25272a;
    --muted: #2b2d30;
    --muted-foreground: #a4a8ac;
    --primary: #8aa9f2;
    --primary-hover: #a6bef6;
    --primary-foreground: #10141f;
    --ring: #8aa9f2;
    --destructive: #f0877e;
    --destructive-hover: #f4a49d;
    --destructive-foreground: #1b100f;
    --secondary: #2b2d30;
    --secondary-hover: #34373a;
    --secondary-foreground: #e7e7e4;
    --accent: #1e2941;
    --accent-foreground: #b8cbf8;
    --border: #323437;
    --border-subtle: #2a2c2f;
    --border-strong: #474a4e;
    --border-control: #83878c;
    --scrim: rgba(0, 0, 0, 0.62);
    --env-billable: #3987e5;
    --env-billable-ink: #5d9dea;
    --env-billable-soft: #1d3350;
    --env-building: #a66bb8;
    --env-building-ink: #b381c3;
    --env-building-soft: #33254a;
    --env-admin: #98a3ad;
    --env-admin-ink: #98a3ad;
    --env-admin-soft: #22272c;
    --env-hobby: #e2a93a;
    --env-hobby-ink: #e2a93a;
    --env-hobby-soft: #3a2e12;
    --env-dormant: #818c97;
    --env-dormant-ink: #848f99;
    --env-dormant-soft: #22272c;
  }
  :root:not([data-theme="light"]) .planner-theme-to-dark { display: none !important; }
}

/* Dark: the person chose it on a light system. */
:root[data-theme="dark"] {
  color-scheme: dark;
  --background: #161718;
  --foreground: #e7e7e4;
  --surface: #1f2022;
  --surface-raised: #25272a;
  --muted: #2b2d30;
  --muted-foreground: #a4a8ac;
  --primary: #8aa9f2;
  --primary-hover: #a6bef6;
  --primary-foreground: #10141f;
  --ring: #8aa9f2;
  --destructive: #f0877e;
  --destructive-hover: #f4a49d;
  --destructive-foreground: #1b100f;
  --secondary: #2b2d30;
  --secondary-hover: #34373a;
  --secondary-foreground: #e7e7e4;
  --accent: #1e2941;
  --accent-foreground: #b8cbf8;
  --border: #323437;
  --border-subtle: #2a2c2f;
  --border-strong: #474a4e;
  --border-control: #83878c;
  --scrim: rgba(0, 0, 0, 0.62);
  --env-billable: #3987e5;
  --env-billable-ink: #5d9dea;
  --env-billable-soft: #1d3350;
  --env-building: #a66bb8;
  --env-building-ink: #b381c3;
  --env-building-soft: #33254a;
  --env-admin: #98a3ad;
  --env-admin-ink: #98a3ad;
  --env-admin-soft: #22272c;
  --env-hobby: #e2a93a;
  --env-hobby-ink: #e2a93a;
  --env-hobby-soft: #3a2e12;
  --env-dormant: #818c97;
  --env-dormant-ink: #848f99;
  --env-dormant-soft: #22272c;
}
:root[data-theme="dark"] .planner-theme-to-dark { display: none !important; }

/* Light shows the moon; dark shows the sun. */
@media not all and (prefers-color-scheme: dark) {
  :root:not([data-theme="dark"]) .planner-theme-to-light { display: none !important; }
}
:root[data-theme="light"] .planner-theme-to-light { display: none !important; }

parameters.functionScript:
var KEY = "nodegx-planner-theme";
function systemTheme() {
  return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}
function chosenTheme() {
  var v = null;
  try { v = window.localStorage.getItem(KEY); } catch (e) { v = window.__plannerTheme || null; }
  return v === 'dark' || v === 'light' ? v : null;
}
function remember(v) {
  window.__plannerTheme = v;
  try { if (v) window.localStorage.setItem(KEY, v); else window.localStorage.removeItem(KEY); } catch (e) {}
}
function applyTheme(v) {
  if (v) document.documentElement.setAttribute('data-theme', v);
  else document.documentElement.removeAttribute('data-theme');
}
applyTheme(chosenTheme());
